create table public.anki_card_changes (
  note_guid text not null,
  ord smallint not null,
  deck_id text,
  change_id bigint default nextval('public.anki_card_change_seq'::regclass) not null,
  changed_at timestamp with time zone default now() not null,
  constraint anki_card_changes_pkey PRIMARY KEY (note_guid, ord)
);

CREATE INDEX anki_card_changes_change ON public.anki_card_changes USING btree (change_id);

alter table public.anki_card_changes enable row level security;
